<?php
$q=trim((string)get('q'));$status=(string)get('status');$sql='SELECT p.*,w.nama_lengkap,w.nik FROM pengajuan p JOIN data_warga w ON w.id=p.data_warga_id WHERE (p.nomor_pengajuan LIKE ? OR w.nama_lengkap LIKE ? OR p.nama_layanan LIKE ?)';$params=['%'.$q.'%','%'.$q.'%','%'.$q.'%'];if(in_array($status,['menunggu','diproses','disetujui','ditolak','selesai'],true)){$sql.=' AND p.status=?';$params[]=$status;}$sql.=' ORDER BY p.created_at DESC LIMIT 300';$stmt=db()->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();
$counts=db()->query("SELECT status,COUNT(*) jumlah FROM pengajuan GROUP BY status")->fetchAll(PDO::FETCH_KEY_PAIR);
?>
<div class="page-heading"><div><h1>Pengajuan Administrasi</h1><p>Periksa dan tindak lanjuti permohonan surat dari warga.</p></div><span class="badge text-bg-warning px-3 py-2"><?= (int)($counts['menunggu']??0) ?> menunggu</span></div>
<div class="row g-2 mb-4"><?php foreach(['menunggu'=>'Menunggu','diproses'=>'Diproses','disetujui'=>'Disetujui','ditolak'=>'Ditolak','selesai'=>'Selesai'] as $key=>$label): ?><div class="col-6 col-md"><a class="panel-card d-block p-3 h-100 <?= $status===$key?'border-army':'' ?>" href="<?= e(url('pengajuan',['status'=>$key])) ?>"><div class="text-muted-2 small"><?= e($label) ?></div><div class="fs-3 fw-bold text-army"><?= (int)($counts[$key]??0) ?></div></a></div><?php endforeach; ?></div>
<section class="panel-card"><div class="data-toolbar"><form method="get" class="d-flex flex-wrap gap-2 flex-grow-1"><input type="hidden" name="page" value="pengajuan"><input class="form-control" style="max-width:360px" name="q" value="<?= e($q) ?>" placeholder="Cari nomor, pemohon, atau layanan"><select class="form-select" style="max-width:180px" name="status"><option value="">Semua status</option><?php foreach(['menunggu','diproses','disetujui','ditolak','selesai'] as $v): ?><option value="<?= $v ?>" <?= $status===$v?'selected':'' ?>><?= ucfirst($v) ?></option><?php endforeach; ?></select><button class="btn btn-outline-army">Terapkan</button></form><span class="text-muted-2 small"><?= count($rows) ?> pengajuan</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Nomor</th><th>Pemohon</th><th>Layanan</th><th>Keperluan</th><th>Tanggal</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7"><div class="empty-state"><i class="bi bi-file-earmark-text"></i><strong>Belum ada pengajuan</strong><span>Pengajuan yang dikirim warga akan muncul di sini.</span></div></td></tr><?php else: foreach($rows as $p): ?><tr><td><strong><?= e($p['nomor_pengajuan']) ?></strong></td><td><?= e($p['nama_lengkap']) ?><small class="d-block text-muted-2"><?= e($p['nik']) ?></small></td><td><?= e($p['nama_layanan']) ?></td><td><?= e(mb_strimwidth($p['keperluan'],0,60,'…')) ?></td><td><?= e(format_date($p['diajukan_pada'])) ?></td><td><?= status_badge($p['status']) ?></td><td><a class="btn btn-sm btn-outline-army" href="<?= e(url('detail-pengajuan',['id'=>$p['id']])) ?>">Periksa</a></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
